# Demonstrated cavity interior dimensions mapped to fill colors.
_FILL_BY_SIZE = {(3, 3): 8, (5, 5): 4, (7, 7): 3}


def transform(grid):
    """Fill enclosed cavities with the color associated with their dimensions."""
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()

    # Mark zero background connected to the exterior using 4-neighbor connectivity.
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    result = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c] or seen[r][c]:
                continue
            region = []
            q.append((r, c))
            seen[r][c] = True
            while q:
                cr, cc = q.popleft()
                region.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                            and not outside[nr][nc] and not seen[nr][nc]):
                        seen[nr][nc] = True
                        q.append((nr, nc))
            rs = [rr for rr, _ in region]
            cs = [cc for _, cc in region]
            fill = _FILL_BY_SIZE.get((max(rs) - min(rs) + 1, max(cs) - min(cs) + 1))
            if fill is not None:
                for rr, cc in region:
                    result[rr][cc] = fill
    return result
